def get_access_token():
    """Recupere un jeton d'acces Admin API via le client credentials grant."""
    url = f"https://{SHOP}/admin/oauth/access_token"
    resp = requests.post(
        url,
        data={
            "grant_type": "client_credentials",
            "client_id": CLIENT_ID,
            "client_secret": CLIENT_SECRET,
        },
        timeout=20,
    )
    resp.raise_for_status()
    return resp.json()["access_token"]


def count_orders(token, search_query, shop=None):
    url = f"https://{shop or SHOP}/admin/api/{API_VERSION}/graphql.json"
    headers = {
        "X-Shopify-Access-Token": token,
        "Content-Type": "application/json",
    }
    total = 0
    cursor = None
    while True:
        payload = {
            "query": GRAPHQL_QUERY,
            "variables": {"query": search_query, "cursor": cursor},
        }
        resp = requests.post(url, headers=headers, json=payload, timeout=20)
        resp.raise_for_status()
        data = resp.json()
        if "errors" in data:
            raise RuntimeError(str(data["errors"]))
        block = data["data"]["orders"]
        total += len(block["edges"])
        if block["pageInfo"]["hasNextPage"]:
            cursor = block["pageInfo"]["endCursor"]
        else:
            break
    return total


def get_access_token_for(store):
    """Comme get_access_token, mais pour une boutique quelconque de
    SHOPIFY_STORES (dict {shop, client_id, client_secret})."""
    url = f"https://{store['shop']}/admin/oauth/access_token"
    resp = requests.post(
        url,
        data={
            "grant_type": "client_credentials",
            "client_id": store["client_id"],
            "client_secret": store["client_secret"],
        },
        timeout=20,
    )
    resp.raise_for_status()
    return resp.json()["access_token"]


